df["Date"] = pd.to_datetime(df["Date"], errors="coerce")

def convert_demand(x):
    x = str(x).strip()

    if x.startswith("(") and x.endswith(")"):
        return -float(x[1:-1])

    return float(x)

df["Order_Demand_Numeric"] = df["Order_Demand"].apply(convert_demand)

m5_header = pd.read_csv(
    M5_SALES_PATH,
    nrows=0
)

m5_day_columns = [
    column
    for column in m5_header.columns
    if column.startswith(
        "d_"
    )
]

m5_sales = pd.read_csv(
    M5_SALES_PATH,
    usecols=[
        "store_id"
    ]
    +
    m5_day_columns
)

m5_calendar = pd.read_csv(
    M5_CALENDAR_PATH,
    usecols=[
        "d",
        "date"
    ]
)

m5_calendar[
    "date"
] = pd.to_datetime(
    m5_calendar[
        "date"
    ]
)

print(
    "Daily periods:",
    len(
        m5_day_columns
    )
)

print(
    "Stores:",
    m5_sales[
        "store_id"
    ].nunique()
)

m5_store_daily_wide = (
    m5_sales
    .groupby(
        "store_id"
    )[
        m5_day_columns
    ]
    .sum()
)

m5_store_daily = (
    m5_store_daily_wide
    .T
    .reset_index()
    .rename(
        columns={
            "index": "d"
        }
    )
    .melt(
        id_vars=[
            "d"
        ],
        var_name="Store",
        value_name="Demand"
    )
)

m5_store_daily = (
    m5_store_daily
    .merge(
        m5_calendar,
        on="d",
        how="left"
    )
)

m5_store_daily.head()

m5_store_daily[
    "Week"
] = (
    m5_store_daily[
        "date"
    ]
    .dt.to_period(
        "W-SUN"
    )
    .dt.end_time
    .dt.normalize()
)

m5_week_day_counts = (
    m5_calendar[
        m5_calendar[
            "d"
        ]
        .isin(
            m5_day_columns
        )
    ]
    .assign(
        Week=lambda x:
            x[
                "date"
            ]
            .dt.to_period(
                "W-SUN"
            )
            .dt.end_time
            .dt.normalize()
    )
    .groupby(
        "Week"
    )
    .size()
)

m5_complete_weeks = (
    m5_week_day_counts[
        m5_week_day_counts
        == 7
    ]
    .index
)

m5_weekly = (
    m5_store_daily[
        m5_store_daily[
            "Week"
        ]
        .isin(
            m5_complete_weeks
        )
    ]
    .groupby(
        [
            "Store",
            "Week"
        ],
        as_index=False
    )[
        "Demand"
    ]
    .sum()
)

print(
    "Stores:",
    m5_weekly[
        "Store"
    ].nunique()
)

print(
    "Complete weeks:",
    m5_weekly[
        "Week"
    ].nunique()
)

print(
    "Store-week observations:",
    len(
        m5_weekly
    )
)

m5_ml = (
    m5_weekly
    .sort_values(
        [
            "Store",
            "Week"
        ]
    )
    .copy()
)

m5_lags = [
    1,
    2,
    4,
    8,
    13,
    26,
    52
]

for lag in m5_lags:

    m5_ml[
        f"lag_{lag}"
    ] = (
        m5_ml
        .groupby(
            "Store"
        )[
            "Demand"
        ]
        .shift(
            lag
        )
    )

for window in [
    4,
    8,
    13
]:

    m5_ml[
        f"rolling_mean_{window}"
    ] = (
        m5_ml
        .groupby(
            "Store"
        )[
            "Demand"
        ]
        .transform(
            lambda x:
                x.shift(1)
                .rolling(
                    window
                )
                .mean()
        )
    )

    m5_ml[
        f"rolling_std_{window}"
    ] = (
        m5_ml
        .groupby(
            "Store"
        )[
            "Demand"
        ]
        .transform(
            lambda x:
                x.shift(1)
                .rolling(
                    window
                )
                .std()
        )
    )

m5_available_weeks = sorted(
    m5_ml_model[
        "Week"
    ]
    .unique()
)

m5_test_weeks = (
    m5_available_weeks[
        -52:
    ]
)

m5_test_start = (
    m5_test_weeks[
        0
    ]
)

m5_train = (
    m5_ml_model[
        m5_ml_model[
            "Week"
        ]
        <
        m5_test_start
    ]
    .copy()
)

m5_test = (
    m5_ml_model[
        m5_ml_model[
            "Week"
        ]
        >=
        m5_test_start
    ]
    .copy()
)

X_train_m5 = (
    m5_train[
        m5_feature_columns
    ]
)

y_train_m5 = (
    m5_train[
        "Demand"
    ]
)

X_test_m5 = (
    m5_test[
        m5_feature_columns
    ]
)

y_test_m5 = (
    m5_test[
        "Demand"
    ]
)

print(
    "Training observations:",
    len(
        m5_train
    )
)

print(
    "Test observations:",
    len(
        m5_test
    )
)

print(
    "Test weeks:",
    m5_test[
        "Week"
    ].nunique()
)
